from fastapi.responses import HTMLResponse

from api.pcna import app


@app.get("/", response_class=HTMLResponse)
def home():
    return HTMLResponse(r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#003b5c"><title>PCNA</title>
<style>
*{box-sizing:border-box}html,body{margin:0;background:#fff;color:#14273a;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}body{min-height:100vh}.shell{max-width:620px;margin:0 auto;padding:calc(8px + env(safe-area-inset-top)) 12px calc(88px + env(safe-area-inset-bottom))}.head{height:64px;display:flex;align-items:center}.logo{height:58px;width:auto}.hero{height:176px;border-radius:18px;overflow:hidden;background:#063f80;box-shadow:0 5px 18px rgba(8,65,120,.18)}.hero img{width:100%;height:100%;object-fit:cover;object-position:center top}.section-title{font-size:32px;font-weight:900;letter-spacing:-.04em;color:#082f66;margin:14px 0 12px}.section-title:after{content:"";display:block;width:62px;height:4px;border-radius:99px;background:#27afe2;margin-top:7px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.card{position:relative;min-height:205px;border:1px solid #cfe0ef;border-radius:18px;background:#fff;padding:14px;color:#082f66;box-shadow:0 4px 16px rgba(9,75,135,.14);cursor:pointer}.icon{width:40px;height:40px;border-radius:50%;background:#075ba7;color:white;display:flex;align-items:center;justify-content:center;font-size:24px;font-weight:900}.card h3{font-size:25px;line-height:1;margin:10px 0 8px;letter-spacing:-.03em}.card p{font-size:12px;line-height:1.3;color:#29496c;max-width:76%}.arrow{position:absolute;right:12px;bottom:12px;width:40px;height:40px;border-radius:50%;background:#075aa7;color:#fff;display:flex;align-items:center;justify-content:center;font-size:27px;font-weight:900}.nav{position:fixed;left:50%;transform:translateX(-50%);bottom:0;width:min(620px,100%);height:calc(70px + env(safe-area-inset-bottom));padding:5px 8px env(safe-area-inset-bottom);background:linear-gradient(90deg,#075ca8,#00326d);border-radius:30px 30px 0 0;display:grid;grid-template-columns:repeat(5,1fr);z-index:20}.nav button{border:0;background:transparent;color:rgba(255,255,255,.75);font:inherit;font-size:12px;font-weight:700;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;padding:0}.nav button.active{color:#fff;font-weight:900}.nav b{font-size:23px}.tool{padding:10px 0}.back{display:inline-block;color:#075ca8;font-weight:800;margin-bottom:8px;cursor:pointer}.tool h1{font-size:31px;line-height:1.05;color:#082f66;margin:4px 0 8px}.copy{color:#66798a;line-height:1.45;margin-bottom:18px}.panel{border:1px solid #d6e2eb;border-radius:16px;padding:14px;margin:10px 0;background:#fff;box-shadow:0 4px 14px rgba(8,79,134,.05)}label{display:block;color:#084f86;font-weight:800;font-size:13px;margin:10px 0 5px}input,textarea,.action{width:100%;font:inherit;border-radius:12px;border:1px solid #b8cad8;background:#fff;color:#14273a;padding:13px}textarea{min-height:110px;resize:vertical}.action{background:#075ca8;color:#fff;font-weight:850;border:none;min-height:48px;margin-top:12px;cursor:pointer}.secondary{background:#eef5fa;color:#084f86}.result{white-space:pre-wrap;border:1px solid #d6e2eb;background:#fbfcfd;border-radius:14px;padding:14px;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px;line-height:1.5;overflow-wrap:anywhere;margin-top:12px}.matches{display:grid;gap:8px;margin-top:10px}.match{border:1px solid #d6e2eb;border-radius:12px;padding:12px;background:#fff}.match strong{display:block;color:#084f86}.muted{color:#66798a;font-size:12px}.error{background:#fff1f0;border:1px solid #f2b8b5;color:#8a1c16;padding:12px;border-radius:12px;margin-top:10px}.success{background:#eef8f1;border:1px solid #b9dec4;color:#245f36;padding:12px;border-radius:12px;margin-top:10px}@media(max-width:430px){.shell{padding-left:10px;padding-right:10px}.hero{height:164px}.section-title{font-size:28px}.card{min-height:190px;padding:12px}.card h3{font-size:21px}.card p{font-size:11px}}
</style></head><body><main class="shell"><div id="app"></div></main>
<nav class="nav" id="nav"><button data-page="home"><b>⌂</b><span>Home</span></button><button data-page="spec"><b>✓</b><span>Specs</span></button><button data-page="search"><b>⌕</b><span>Products</span></button><button data-page="virtual"><b>◇</b><span>Virtuals</span></button><button data-page="quote"><b>$</b><span>Quotes</span></button></nav>
<script>
const app=document.getElementById('app');
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
let page=new URLSearchParams(location.search).get('page')||'home';
function setPage(p){page=p;history.pushState({},'',p==='home'?'/' : '/?page='+p);render()}
window.onpopstate=()=>{page=new URLSearchParams(location.search).get('page')||'home';render()};
document.querySelectorAll('#nav button').forEach(b=>b.onclick=()=>setPage(b.dataset.page));
function nav(){document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page))}
function tool(title,copy,body){return `<div class="tool"><div class="back" onclick="setPage('home')">← Home</div><h1>${title}</h1><div class="copy">${copy}</div><div class="panel">${body}</div></div>`}
function home(){return `<div class="head"><a href="https://www.pcna.com/en-us"><img class="logo" src="https://raw.githubusercontent.com/cmhart13-boop/PCNA-App/main/IMG_2337.webp" alt="PCNA"></a></div><div class="hero"><img src="https://assets.pcna.com/image/upload/ar_16:7,c_fill,g_north,pg_1,q_auto,f_jpg/Mkt_Dept/2026%20Jobs/2026-0817_Web_Messaging/0817_Web_PCNA_Hero_m.jpg" alt="PCNA lifestyle"></div><div class="section-title">What do you need?</div><div class="grid">${[['spec','✓','Spec Sample Order','Tell Nova what you need and build the verified PCNA order.'],['virtual','◇','Virtuals / Designs','Capture product, decoration and art direction in one request.'],['quote','$','Quote Request','Quote a verified PCNA product at the requested quantity.'],['projects','□','Projects','Keep customer project notes and requests together.']].map(x=>`<div class="card" onclick="setPage('${x[0]}')"><div class="icon">${x[1]}</div><h3>${x[2]}</h3><p>${x[3]}</p><div class="arrow">→</div></div>`).join('')}</div>`}
async function api(params){const r=await fetch('/api/pcna?'+new URLSearchParams(params));const d=await r.json();if(!r.ok)throw new Error(d.detail||'Request failed');return d}
function searchPage(){app.innerHTML=tool('Product Search','Search the verified PCNA starter catalog by product name or item number.',`<label>Product name or item number</label><input id="q" placeholder="Dade Polo, Stanley 30 oz, 1603-02..."><button class="action" id="go">Search verified products</button><div id="out"></div>`);document.getElementById('go').onclick=async()=>{const out=document.getElementById('out');out.innerHTML='';try{const d=await api({action:'search',q:document.getElementById('q').value});out.innerHTML='<div class="matches">'+d.results.map(r=>`<div class="match"><strong>${esc(r.product_name)}</strong><div>${esc(r.item_number)}</div><div class="muted">${esc([r.brand,r.color].filter(Boolean).join(' · '))}</div></div>`).join('')+'</div>'}catch(e){out.innerHTML='<div class="error">'+esc(e.message)+'</div>'}}}
function quotePage(){app.innerHTML=tool('Quote Request','Resolve a verified product and return its decorated USD price tier.',`<label>Product or item number</label><input id="q" placeholder="Dade Polo or TM16398"><label>Quantity</label><input id="qty" type="number" min="1" value="100"><button class="action" id="go">Build quote</button><div id="out"></div>`);document.getElementById('go').onclick=async()=>{const out=document.getElementById('out');try{const d=await api({action:'quote',q:q.value,qty:qty.value});out.innerHTML=`<div class="result">Product: ${esc(d.product_name)}\nItem Number: ${esc(d.item_number)}\nQuantity: ${d.quantity}\nMOQ Tier: ${d.moq_tier}\nUnit Price: $${Number(d.unit_price).toFixed(2)} ${esc(d.currency)}\nSchedule: ${esc(d.schedule)}${d.below_moq?'\nNote: Requested quantity is below MOQ.':''}</div>`}catch(e){out.innerHTML='<div class="error">'+esc(e.message)+'</div>'}}}
function specPage(){app.innerHTML=tool('Spec Sample Order','Build the clean PCNA spec-order format from a verified product match.',`<label>Product or item number</label><input id="q" placeholder="Dade Polo or TM16398"><label>Color</label><input id="color" value="Black"><label>Size (if applicable)</label><input id="size"><label>Decoration method</label><input id="method" value="Embroidery"><label>Decoration location</label><input id="location" value="Left Chest"><label>Imprint color</label><input id="imprint" value="White"><label>Ship To</label><textarea id="ship"></textarea><button class="action" id="go">Build spec order</button><div id="out"></div>`);document.getElementById('go').onclick=async()=>{const out=document.getElementById('out');try{const d=await api({action:'spec',q:q.value,color:color.value,size:size.value,method:method.value,location:location.value,imprint:imprint.value,ship_to:ship.value});out.innerHTML=`<div class="result" id="order">${esc(d.order)}</div><button class="action secondary" id="copy">Copy order</button>`;copy.onclick=()=>navigator.clipboard.writeText(d.order)}catch(e){out.innerHTML='<div class="error">'+esc(e.message)+'</div>'}}}
function virtualPage(){app.innerHTML=tool('Virtuals / Designs','Capture the complete virtual request without losing product, decoration, or art direction details.',`<label>Virtual request</label><textarea id="v" placeholder="Dade Polo, black, left chest embroidery, white logo…"></textarea><button class="action" id="save">Save request</button><div id="out"></div>`);v.value=localStorage.getItem('pcna_virtual_request')||'';save.onclick=()=>{localStorage.setItem('pcna_virtual_request',v.value);out.innerHTML='<div class="success">Saved on this device.</div>'}}
function projectsPage(){const items=JSON.parse(localStorage.getItem('pcna_projects')||'[]');app.innerHTML=tool('Projects','Save lightweight customer/project notes on this device.',`<label>Project name</label><input id="pn"><label>Notes</label><textarea id="notes"></textarea><button class="action" id="save">Save project</button><div id="list" class="matches">${items.map(x=>`<div class="match"><strong>${esc(x.name||'Untitled Project')}</strong><div class="muted">${esc(x.notes||'')}</div></div>`).join('')}</div>`);save.onclick=()=>{const next=[...items,{name:pn.value,notes:notes.value}];localStorage.setItem('pcna_projects',JSON.stringify(next));projectsPage()}}
function render(){nav();if(page==='search')return searchPage();if(page==='quote')return quotePage();if(page==='spec')return specPage();if(page==='virtual')return virtualPage();if(page==='projects')return projectsPage();app.innerHTML=home()}
render();
</script></body></html>''')
